Lemma free_pre_spec : forall ra sp gp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (p TCX T top bot lo : Z) (b : bool) (tr : list Z) (ch : list (Z * Z)),
  (0 <= p < 2^47)%Z ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 2288)%Z -> (kHighShadowEnd + 8 <= lo)%Z ->
  (bv_unsigned sp <= 2^47)%Z ->
  (0 <= bot < top)%Z -> (top < 2^64)%Z ->
  (* [comment removed for export] *)
  unwind_trace free_pc 4096 bot top 30 (bv_unsigned sp) ((bv_unsigned ra, bv_unsigned s0) :: ch) = Some tr ->
  chain_cells [(T + 3168, T + 3169); (2883016, 2883020); (2299200, 2827632); (bv_unsigned sp - 2288, bv_unsigned sp)]%Z m (bv_unsigned s0) ch ->
  ia_state b m ->
