  chain_cells [(T + 3168, T + 3169); (2883016, 2883020); (2299200, 2827632); (bv_unsigned sp - 2288, bv_unsigned sp)]%Z m (bv_unsigned s0) ch ->
  ia_state b m ->
  rw_cells asegs m 0x2117b8 [C8 (Z_to_bv 64 0x2bfde0)] ->
  rw_cells asegs m g_GOT_common_flags [C8 (Z_to_bv 64 g_common_flags)] ->
